/* 스와이프 가능한 칩 행: 더 스크롤할 구간이 남아있는 쪽에만 16px 페이드 표시 */
function ScrollChipRow({ chips, active, onChipClick }) {
  const ref = useRef(null);
  const rafRef = useRef(null);
  const timerRef = useRef(null);
  const [edge, setEdge] = useState({ left: false, right: false });

  const update = () => {
    const el = ref.current;
    if (!el) return;
    const { scrollLeft, scrollWidth, clientWidth } = el;
    const overflowing = scrollWidth > clientWidth + 1;
    setEdge({
      left: overflowing && scrollLeft > 2,
      right: overflowing && scrollLeft < scrollWidth - clientWidth - 2,
    });
  };

  useEffect(() => { update(); }, [chips]);

  const animateTo = (target, duration, onDone) => {
    const el = ref.current;
    if (!el) return;
    const start = el.scrollLeft;
    const t0 = performance.now();
    const ease = (t) => 1 - Math.pow(1 - t, 3);
    const step = (now) => {
      const p = Math.min(1, (now - t0) / duration);
      el.scrollLeft = start + (target - start) * ease(p);
      update();
      if (p < 1) rafRef.current = requestAnimationFrame(step);
      else onDone && onDone();
    };
    rafRef.current = requestAnimationFrame(step);
  };

  useEffect(() => {
    const el = ref.current;
    if (!active || !el) {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      if (timerRef.current) clearTimeout(timerRef.current);
      el?.scrollTo({ left: 0 });
      return;
    }
    const max = el.scrollWidth - el.clientWidth;
    if (max <= 0) return;
    let cancelled = false;
    const toEnd = () => animateTo(max, 1100, () => {
      if (cancelled) return;
      timerRef.current = setTimeout(toStart, 1000);
    });
    const toStart = () => animateTo(0, 1100, () => {
      if (cancelled) return;
      timerRef.current = setTimeout(toEnd, 1000);
    });
    toEnd();
    return () => {
      cancelled = true;
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [active, chips]);

  return (
    <div style={{ position: 'relative', marginTop: 16 }}>
      <div ref={ref} onScroll={update} className="no-scrollbar" style={{ display: 'flex', gap: 6, overflowX: 'auto', scrollbarWidth: 'none', msOverflowStyle: 'none' }}>
        {chips.map((c) => <Chip key={c} onClick={onChipClick}>{c}</Chip>)}
      </div>
      {edge.left && <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: 16, background: 'linear-gradient(90deg, #FFFFFF, rgba(255,255,255,0))', pointerEvents: 'none' }} />}
      {edge.right && <div style={{ position: 'absolute', right: 0, top: 0, bottom: 0, width: 16, background: 'linear-gradient(270deg, #FFFFFF, rgba(255,255,255,0))', pointerEvents: 'none' }} />}
    </div>
  );
}

function PersonaCard({ card, selected, onSelect, onPreview, onChipClick }) {
  return (
    <div
      onClick={() => onSelect(card.id)}
      style={{
        width: 270, minWidth: 270, height: 294, borderRadius: 16,
        border: `2px solid ${selected ? C.dark : C.borderLight}`,
        background: C.white, flexShrink: 0, cursor: 'pointer', overflow: 'hidden',
        padding: '16px 18px 18px', boxSizing: 'border-box', fontFamily: FONT,
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', height: 24, minWidth: 0 }}>
        <span style={{ fontSize: 17, fontWeight: 600, color: C.textPrimary, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', minWidth: 0 }}>{card.label}</span>
        <span style={{ marginLeft: 8, flexShrink: 0 }}><CountBadge>{card.chips.length}개 항목</CountBadge></span>
        <div style={{ flex: 1, minWidth: 8 }} />
        <div style={{
          width: 22.5, height: 22.5, borderRadius: '50%', flexShrink: 0,
          border: selected ? 'none' : `1.5px solid ${C.border}`,
          background: selected ? C.yellow : 'transparent',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          {selected && <Check size={13} color={C.textPrimary} strokeWidth={3} />}
        </div>
      </div>

      <div style={{ marginTop: 8, fontSize: 13.5, color: C.textTertiary, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{card.tagline}</div>

      <div style={{ marginTop: 16, display: 'flex', justifyContent: 'center' }}>
        <Illustration icon={card.icon} />
      </div>

      <ScrollChipRow chips={card.chips} active={selected} onChipClick={onChipClick} />

      <button
        onClick={(e) => { e.stopPropagation(); onPreview(card); }}
        style={{ marginTop: 16, width: '100%', height: 43, borderRadius: 21.5, border: `1px solid ${C.border}`, background: 'transparent', fontSize: 14.5, fontWeight: 500, color: C.textPrimary, cursor: 'pointer', fontFamily: FONT }}
      >
        미리보기
      </button>
    </div>
  );
}

