// 업로드받은 실제 로고 이미지가 있으면 최우선 사용 (그룹사 공용 로고는 같은
// 계열 종목끼리 재사용 - 삼성전자/삼성SDI, LG에너지솔루션/LG화학 등).
// 없으면 구글 파비콘으로, 그것도 없으면 이니셜로 폴백.
const STOCK_LOGOS = {
  '005930': 'data:image/png;base64,',
  '006400': 'data:image/png;base64,',
  '000660': 'data:image/png;base64,',
  '373220': 'data:image/png;base64,',
  '051910': 'data:image/png;base64,',
  '003670': 'data:image/png;base64,',
  '329180': 'data:image/png;base64,',
  '034020': 'data:image/png;base64,',
  '애플': 'data:image/png;base64,',
  '메타': 'data:image/png;base64,',
  '247540': 'data:image/png;base64,',
  '068270': 'data:image/png;base64,',
  '323410': 'data:image/png;base64,',
  '035720': 'data:image/png;base64,',
  '035420': 'data:image/png;base64,',
};

function Avatar({ name, code, size = 40 }) {
  const [imgError, setImgError] = useState(false);
  const radius = size === 40 ? 16 : size * 0.4;
  const logo = (code && STOCK_LOGOS[code]) || STOCK_LOGOS[name];
  if (logo && !imgError) {
    return (
      <img
        src={logo}
        alt={name}
        onError={() => setImgError(true)}
        style={{ width: size, height: size, borderRadius: radius, objectFit: 'cover', flexShrink: 0, background: '#E8E9EC' }}
      />
    );
  }
  return <div style={{ width: size, height: size, borderRadius: radius, background: '#E8E9EC', flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: size * 0.4, fontWeight: 600, color: C.textTertiary }}>{name[0]}</div>;
}
function Delta({ c, up, size = 13 }) {
  return (
    <span style={{ fontSize: size, fontWeight: 600, color: up ? UP : DOWN, display: 'inline-flex', alignItems: 'center', gap: 2, verticalAlign: '-1px' }}>
      <svg width="12.5" height="12.5" viewBox="0 0 20 20">
        {up
          ? <path d="M8.93926 6.54041C9.52505 5.95463 10.4748 5.95463 11.0606 6.54041L15.8583 11.3381C16.8032 12.2831 16.134 13.8988 14.7976 13.8988H5.20223C3.86587 13.8988 3.19662 12.2831 4.14157 11.3381L8.93926 6.54041Z" fill="#FF0019" />
          : <path d="M11.0607 13.4596C10.4749 14.0454 9.5252 14.0454 8.93941 13.4596L4.14172 8.66189C3.19677 7.71694 3.86602 6.10123 5.20238 6.10123L14.7978 6.10123C16.1341 6.10123 16.8034 7.71694 15.8584 8.66189L11.0607 13.4596Z" fill="#0090FF" />}
      </svg>
      {c}
    </span>
  );
}
function CardShell({ title, subtitle, children, showCheck = true, showTitle = true }) {
  const [checked, setChecked] = useState(true);
  return (
    <div>
      {showTitle && (
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <span style={{ fontSize: 20, fontWeight: 700, lineHeight: 1.4, color: C.dark }}>{title}</span>
        {showCheck && (
          <div onClick={(e) => { e.stopPropagation(); setChecked(!checked); }} style={{ width: 22, height: 22, borderRadius: '50%', background: checked ? C.yellow : 'transparent', border: checked ? 'none' : `1.5px solid ${C.border}`, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', boxSizing: 'border-box' }}>
            {checked && <Check size={13} color={C.textPrimary} strokeWidth={3} />}
          </div>
        )}
      </div>
      )}
      {subtitle && <div style={{ marginTop: 4, fontSize: 14, color: C.textTertiary }}>{subtitle}</div>}
      {children}
    </div>
  );
}
function Tag({ children }) {
  return <span style={{ display: 'inline-block', background: C.yellow, color: C.textPrimary, fontSize: 12, fontWeight: 500, borderRadius: 100, padding: '7px 14px' }}>{children}</span>;
}
function Note({ children }) {
  return <div style={{ background: '#F7F9F9', borderRadius: 10, padding: 12, marginTop: 8, fontSize: 13, color: C.textTertiary, lineHeight: 1.6 }}>{children}</div>;
}
function ArrowIcon({ up }) {
  return (
    <svg width="16" height="16" viewBox="0 0 20 20" style={{ transform: up ? 'none' : 'rotate(180deg)', display: 'inline-block', verticalAlign: 'middle' }}>
      <path d="M14 12L10 8L6 12" stroke="#939AA2" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" fill="none" />
    </svg>
  );
}
function Underline({ items, active, onChange, disabled = [] }) {
  return (
    <div style={{ marginTop: 12 }}>
      <div style={{ display: 'flex', gap: 16 }}>
        {items.map((t) => {
          const isDisabled = disabled.includes(t);
          return (
            <button
              key={t}
              onClick={() => !isDisabled && onChange(t)}
              style={{
                background: 'none', border: 'none', cursor: 'pointer', padding: '0 0 8px', fontFamily: FONT, fontSize: 16,
                fontWeight: 700,
                lineHeight: 1.4,
                color: C.dark,
                borderBottom: active === t ? `2px solid ${C.textPrimary}` : 'none',
              }}
            >{t}</button>
          );
        })}
      </div>
      <div style={{ borderTop: `1px solid ${C.borderLight}`, margin: '0 -16px' }} />
    </div>
  );
}
// items는 순수 문자열(일반 필터탭) 또는 { label, code } 객체(종목 칩 -
// 왼쪽에 20x20 로고/이니셜 썸네일이 붙음)를 섞어서 받을 수 있음.
function PillTabs({ items, active, onChange }) {
  return (
    <div className="no-scrollbar" style={{ display: 'flex', gap: 6, marginTop: 12, overflowX: 'auto', scrollbarWidth: 'none' }}>
      {items.map((item) => {
        const isStock = typeof item !== 'string';
        const label = isStock ? item.label : item;
        return (
          <button
            key={label}
            onClick={() => onChange(label)}
            style={{
              flexShrink: 0, height: 32, padding: isStock ? '0 12px 0 6px' : '0 12px', borderRadius: 8, border: 'none', cursor: 'pointer',
              fontFamily: FONT, fontSize: 13, fontWeight: active === label ? 700 : 500,
              background: active === label ? C.dark : C.chipBg, color: active === label ? C.white : C.textSecondary,
              display: 'flex', alignItems: 'center', gap: 6,
            }}
          >
            {isStock && <Avatar name={label} code={item.code} size={20} />}
            {label}
          </button>
        );
      })}
    </div>
  );
}
function MoreLink() {
  return (
    <div style={{ marginTop: 12 }}>
      <div style={{ borderTop: `1px solid ${C.borderLight}`, margin: '0 -16px' }} />
      <div style={{ paddingTop: 12, textAlign: 'center', fontSize: 13, fontWeight: 500, color: C.textTertiary }}>더보기 ›</div>
    </div>
  );
}

