function IndexCard({ showCheck = true, subtitle } = {}) {
  const [kospiLive, setKospiLive] = useState(null); // null = not loaded yet, keeps static value shown
  useEffect(() => {
    let cancelled = false;
    fetch('/api/kiwoom/index')
      .then((r) => r.json())
      .then((data) => {
        if (!cancelled && !data.error) setKospiLive(data);
      })
      .catch(() => {}); // network hiccup: silently keep the static placeholder value
    return () => { cancelled = true; };
  }, []);
  const idx = IDX.map((i) =>
    i.n === '코스피' && kospiLive
      ? { ...i, v: kospiLive.value, c: kospiLive.changePct, up: kospiLive.up }
      : i
  );
  return (
    <CardShell title="지수" showCheck={showCheck} subtitle={subtitle}>
      <div style={{ position: 'relative', marginTop: 12 }}>
        <div className="no-scrollbar" style={{ display: 'flex', gap: 8, overflowX: 'auto', scrollbarWidth: 'none' }}>
          {idx.map((i) => (
            <div key={i.n} style={{ flexShrink: 0, width: 116, background: '#F7F9F9', borderRadius: 10, padding: 12 }}>
              <div style={{ fontSize: 14, fontWeight: 500, color: C.textPrimary, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{i.n}</div>
              <div style={{ fontSize: 16, fontWeight: 500, color: i.up ? UP : DOWN, marginTop: 2 }}>{i.v}</div>
              <div style={{ marginTop: -4 }}><Delta c={i.c} up={i.up} size={12} /></div>
            </div>
          ))}
        </div>
        <div style={{ position: 'absolute', right: 0, top: 0, bottom: 0, width: 24, background: 'linear-gradient(270deg, #FFFFFF, rgba(255,255,255,0))', pointerEvents: 'none' }} />
      </div>
    </CardShell>
  );
}

