// qty(보유수량)·avgPrice(매입단가)만 임의로 정하고, 나머지(현재가/등락률/평가금액)는
// 전부 계산값 - 라이브 시세가 오면 그 값으로, 안 오면 avgPrice를 현재가로 가정해 계산.
const HOLDINGS = [
  { n: '카카오', t: '035720', qty: 10, avgPrice: 48500, price: 52300 },
  { n: 'NAVER', t: '035420', qty: 1, avgPrice: 224000, price: 218500 },
  { n: 'LG에너지솔루션', t: '373220', qty: 2, avgPrice: 398000, price: 412000 },
];

function formatWon(n) {
  return `${Math.round(n).toLocaleString('ko-KR')}원`;
}

function PortfolioCard({ showCheck = true, subtitle, showTitle = true } = {}) {
  const [quotes, setQuotes] = useState({}); // { [code]: { price, changePctRaw, up } }
  useEffect(() => {
    let cancelled = false;
    const codes = HOLDINGS.map((h) => h.t).join(',');
    const load = () => {
      fetch(`/api/kiwoom/quote?codes=${codes}`)
        .then((r) => r.json())
        .then((data) => {
          if (!cancelled && !data.error && data.quotes) setQuotes(data.quotes);
        })
        .catch(() => {}); // network hiccup: silently keep last known prices
    };
    load();
    const id = setInterval(load, 15000); // poll for real-time movement
    return () => { cancelled = true; clearInterval(id); };
  }, []);

  const rows = HOLDINGS.map((h) => {
    const live = quotes[h.t];
    const price = live ? live.price : h.price;
    return { ...h, price, evalAmount: price * h.qty, costAmount: h.avgPrice * h.qty };
  });
  const totalEval = rows.reduce((sum, r) => sum + r.evalAmount, 0);
  const totalCost = rows.reduce((sum, r) => sum + r.costAmount, 0);
  const changeAmount = totalEval - totalCost;
  const changePct = totalCost ? (changeAmount / totalCost) * 100 : 0;
  const up = changeAmount >= 0;

  return (
    <CardShell title="포트폴리오" showCheck={showCheck} subtitle={subtitle} showTitle={showTitle}>
      <div style={{ marginTop: 12 }}>
        <div style={{ fontSize: 12.5, color: C.textTertiary }}>총 평가액</div>
        <div style={{ fontSize: 28, fontWeight: 600, lineHeight: 1.4, color: C.textPrimary, marginTop: 0 }}>{formatWon(totalEval)}</div>
        <div style={{ marginTop: -4 }}><Delta c={`${Math.abs(changePct).toFixed(2)}% (${formatWon(Math.abs(changeAmount))})`} up={up} size={13} /></div>
      </div>
      <div style={{ marginTop: 14, display: 'flex', flexDirection: 'column', gap: 12 }}>
        {rows.map((h, i) => {
          const rowUp = h.price >= h.avgPrice;
          const rowPct = h.avgPrice ? Math.abs(((h.price - h.avgPrice) / h.avgPrice) * 100) : 0;
          return (
            <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <Avatar name={h.n} code={h.t} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 14, fontWeight: 500, color: C.textPrimary, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{h.n}</div>
                <div style={{ fontSize: 12, color: C.textTertiary }}>{h.qty}주</div>
              </div>
              <div style={{ textAlign: 'right' }}>
                <Delta c={`${rowPct.toFixed(2)}%`} up={rowUp} />
                <div style={{ fontSize: 12.5, color: C.textTertiary, marginTop: 2 }}>{formatWon(h.evalAmount)}</div>
              </div>
            </div>
          );
        })}
      </div>
    </CardShell>
  );
}

